        stack = []
        for op in circuit:
            if op == 'PUSH':
                stack.append(0)
            elif op == 'ADD':
                if len(stack) < 2:
                    return False
                stack[-2] += stack.pop()
            elif op == 'MUL':
                if len(stack) < 2:
                    return False
                stack[-2] *= stack.pop()
            else:
                return False
        return len(stack) == 1 and stack[0] == 0

    def circuit_width(circuit):
        max_depth = 0
        current_depth = 0
        for op in circuit:
            if op == 'PUSH':
                current_depth += 1
